/* =========== GRAFICA: stile taccuino =========== */
const INKS='class="k"',INKF='class="kf"';
const TH={valle:168,betulle:162,torbiera:172,lago:176,altopiano:138,passo:104,gola:178};
function seedR(s){const x=Math.sin(s*9301+49297)*233280;return x-Math.floor(x)}
function profile(t){const n=t.terr.length,w=390/n,keys=[[0,TH[t.terr[0]]]];
 t.terr.forEach((tp,i)=>{const x0=i*w;keys.push([x0+w/2,TH[tp]+(seedR(t.n*31+i)-.5)*16-(tp==='passo'?8:0)]);
  keys.push([x0+w,i<n-1?(TH[tp]+TH[t.terr[i+1]])/2:TH[tp]])});
 const pts=[];for(let k=0;k<keys.length-1;k++){const [xa,ya]=keys[k],[xb,yb]=keys[k+1];for(let x=xa;x<xb;x+=6){const f=(1-Math.cos(Math.PI*(x-xa)/(xb-xa)))/2;pts.push([x,ya+(yb-ya)*f])}}
 pts.push(keys[keys.length-1]);return pts}
function yAt(pts,x){for(let i=1;i<pts.length;i++)if(pts[i][0]>=x){const [xa,ya]=pts[i-1],[xb,yb]=pts[i];return ya+(yb-ya)*((x-xa)/((xb-xa)||1))}return pts[pts.length-1][1]}
const pathD=(pts)=>pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
function farHills(seed){let d='';for(let i=0;i<=8;i++){const x=i*48.75,y=70+seedR(seed+i)*55;d+=`${i?' L':'M'}${x.toFixed(0)} ${y.toFixed(0)}`}return d}
function sky(clock,wx){const f=clamp((clock-300)/1080,0,1),th=Math.PI*(1-f),sx=195+165*Math.cos(th),sy=118-92*Math.sin(th);
 const late=clock>1140,grey=wx==='pioggia'||wx==='nebbia';let s='';
 if(late)s+=`<rect x="0" y="0" width="390" height="240" fill="#E8A35A" opacity=".10"></rect>`;
 s+=`<path d="M30 118 A165 92 0 0 1 360 118" fill="none" stroke="#8C7B6B" stroke-width="1.2" stroke-dasharray="2 5"></path>`;
 const sun=`<g transform="translate(${sx.toFixed(0)} ${sy.toFixed(0)})"><circle r="14" fill="${late?'#E3843E':'#EDB447'}" opacity="${grey?.45:.95}"></circle><circle r="14" fill="none" stroke-width="1.4" ${INKS}></circle><g class="raggi"><path d="M0 -20 V-26 M15 -15 L19 -19 M20 0 H26 M15 15 L19 19 M0 20 V26 M-15 15 L-19 19 M-20 0 H-26 M-15 -15 L-19 -19" stroke-width="1.5" stroke-linecap="round" ${INKS}></path></g></g>`;
 const off=(cx)=>Math.abs(cx-sx)<70?(sx<195?Math.min(150,330-cx):Math.max(-150,40-cx)):0;if(wx!=='pioggia'&&wx!=='nebbia')s+=sun;
 if(wx!=='sole'){const cf=grey?'#A9ADA9':'#E6DCC6';
  const c1=`<path d="M128 52 C126 40 140 34 150 40 C156 28 176 30 178 44 C190 42 196 54 186 60 H132 C124 60 122 54 128 52 Z" fill="${cf}" stroke-width="1.3" ${INKS}></path>`;
  const c2=`<path d="M262 40 C262 31 274 27 281 32 C287 23 302 26 302 36 C311 35 314 45 306 49 H266 C259 49 257 43 262 40 Z" fill="${cf}" stroke-width="1.2" ${INKS}></path>`;
  const c3=`<path d="M40 30 C40 22 50 18 56 22 C60 14 74 16 74 26 C82 25 84 34 78 37 H44 C38 37 37 32 40 30 Z" fill="${cf}" stroke-width="1.2" ${INKS}></path>`;
  s+=`<g transform="translate(${grey?0:off(160)} 0)"><g class="nuvola">${c1}</g></g><g transform="translate(${grey?0:off(285)} 0)"><g class="nuvola">${c2}</g></g>${grey?c3:''}`}
 return s}
