function land(wx,clock,seed,groundY){const grey=wx==='pioggia'||wx==='nebbia',gy=groundY||182;
 return `${SDEFS}${sky(clock,wx)}<path d="${farHills(seed)} L390 240 L0 240 Z" fill="${grey?'#8E9AA0':'#8FA9B8'}" opacity=".42" filter="url(#washS)"></path><path d="${farHills(seed)} L390 240 L0 240 Z" fill="url(#hatchS)" opacity=".45"></path><path d="${farHills(seed)}" fill="none" stroke-width="2" stroke-linejoin="round" ${INKS} filter="url(#inkS)"></path>
 <path d="M0 ${gy} C90 ${gy-8} 200 ${gy+6} 390 ${gy-4} L390 240 L0 240 Z" fill="${grey?'#8C9A72':'#9DB27A'}" opacity=".6" filter="url(#washS)"></path><path d="M0 ${gy} C90 ${gy-8} 200 ${gy+6} 390 ${gy-4} L390 240 L0 240 Z" fill="url(#dotsS)"></path><path d="M0 ${gy} C90 ${gy-8} 200 ${gy+6} 390 ${gy-4}" fill="none" stroke-width="2.4" ${INKS} filter="url(#inkS)"></path>`}
function big(s,x,y,k){return `<g transform="translate(${x} ${y}) scale(${k}) translate(${-x} ${-y})">${s}</g>`}
function kitColor(bases,def){for(const k of S.kit){const it=ITEM_BY[k];if(it&&it.color&&bases.includes(it.base))return it.color}return def}
function packColor(){return kitColor(['zainoClassico','zainoUL'],has('zainoUL')?'#7E9A5B':'#C98B3A')}
