function trekKm(){let km=0;for(let i=0;i<S.tappa;i++){if(TAPPE[i].extra&&!S.timbri.includes('La vetta del Gáisi'))continue;km+=TAPPE[i].km}const t=TAPPE[S.tappa];if(t){km+=endKind()==='completo'?t.km:Math.round(t.km*Math.min(S.seg,t.terr.length)/t.terr.length)}return km}
/* =========== SCENE DI CASA: la vita di tutti i giorni =========== */
function seasonOf(m){return m===12||m<=2?'inverno':m<=5?'primavera':m<=8?'estate':'autunno'}
function windowView(x,y,w,h,night,rainy){const se=seasonOf(H.mese);const sky=night?'#2F3E52':rainy?'#A9B2B8':'#BFD6E4';
 let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${sky}" opacity=".85"></rect>`;
 s+=`<path d="M${x} ${y+h*.72} L${x+w*.3} ${y+h*.45} L${x+w*.5} ${y+h*.6} L${x+w*.75} ${y+h*.35} L${x+w} ${y+h*.6} V${y+h} H${x} Z" fill="${se==='inverno'?'#E9EEF0':'#8FA9B8'}" opacity=".8"></path>`;
 if(se==='autunno')s+=`<circle cx="${x+w*.2}" cy="${y+h*.85}" r="${w*.12}" fill="#D9842E" opacity=".85"></circle><circle cx="${x+w*.8}" cy="${y+h*.88}" r="${w*.1}" fill="#B5452E" opacity=".8"></circle>`;
 if(se==='primavera'||se==='estate')s+=`<circle cx="${x+w*.2}" cy="${y+h*.86}" r="${w*.13}" fill="#7E9A5B" opacity=".85"></circle><circle cx="${x+w*.82}" cy="${y+h*.88}" r="${w*.11}" fill="#9DB27A" opacity=".85"></circle>`;
 if(night)s+=`<circle cx="${x+w*.75}" cy="${y+h*.22}" r="${w*.08}" fill="#F2E6CC"></circle>`;
 else if(se==='estate'&&!rainy)s+=`<circle cx="${x+w*.78}" cy="${y+h*.2}" r="${w*.09}" fill="#EDB447"></circle>`;
 if(rainy)s+=`<g stroke="#4F6B80" stroke-width="1" opacity=".8"><path class="goccia" d="M${x+6} ${y} L${x} ${y+h} M${x+w*.3} ${y} L${x+w*.3-6} ${y+h} M${x+w*.6} ${y} L${x+w*.6-6} ${y+h} M${x+w*.9} ${y} L${x+w*.9-6} ${y+h}"></path></g>`;
 if(se==='inverno')s+=`<g fill="#FFFFFF"><circle cx="${x+w*.2}" cy="${y+h*.3}" r="1.6"></circle><circle cx="${x+w*.5}" cy="${y+h*.2}" r="1.4"></circle><circle cx="${x+w*.7}" cy="${y+h*.5}" r="1.6"></circle><circle cx="${x+w*.35}" cy="${y+h*.6}" r="1.3"></circle></g>`;
 s+=`<path d="M${x} ${y} H${x+w} V${y+h} H${x} Z M${x+w/2} ${y} V${y+h} M${x} ${y+h/2} H${x+w}" fill="none" stroke-width="3" class="k" filter="url(#inkS)"></path>`;
 return s}
