function pg(){return PG[(typeof H!=='undefined'&&H&&H.pg)||'marco']||PG.marco}
function pgName(){return (typeof H!=='undefined'&&H&&H.nome)||pg().name}
const HAT='#C9B07A';
/* testa di profilo, rivolta a destra */
function headSide(x,y){const p=pg();let s=`<g transform="translate(${x} ${y})">`;
 if(p.style==='braid')s+=`<path d="M-5 -2 C-10 4 -10 12 -7 18" fill="none" stroke="${p.hair}" stroke-width="3.2" stroke-linecap="round"></path>`;
 if(p.style==='bob')s+=`<path d="M-7 -3 C-9 4 -7 8 -3 8 L-2 0 Z" fill="${p.hair}" class="k" stroke-width=".8"></path>`;
 s+=`<circle r="6.2" fill="${p.skin}" class="k" stroke-width="1.3"></circle>`;
 const hair={short:'M-6 -1 C-7 -7 3 -9 6 -4 C3 -5 -1 -4 -2 -1 Z',curly:'M-7 0 C-9 -8 2 -11 7 -5 C8 -3 5 -3 3 -4 C0 -4 -2 -2 -3 0 Z',braid:'M-6 0 C-7 -7 3 -9 6 -4 C3 -5 -1 -4 -3 -1 Z',bob:'M-7 2 C-8 -7 3 -9 7 -4 C3 -5 0 -4 -2 -1 L-3 3 Z'}[p.style];
 s+=`<path d="${hair}" fill="${p.hair}" class="k" stroke-width=".9"></path>`;
 if(p.beard)s+=`<path d="M-1 3 C1 7 4 7 6 3" fill="none" stroke="${p.hair}" stroke-width="2.2" opacity=".55"></path>`;
 if(p.band)s+=`<path d="M-6 -3 C-2 -6 3 -6 6 -4" fill="none" stroke="${p.band}" stroke-width="1.6"></path>`;
 s+=`<circle cx="3" cy="-1" r=".9" fill="#2B231D"></circle><path d="M6 0 L8 1.6 L6 2.4" fill="${p.skin}" class="k" stroke-width=".8"></path>`;
 if(p.glasses)s+=`<circle cx="3" cy="-1" r="2.2" fill="none" stroke="#2B231D" stroke-width=".8"></circle>`;
 if(has('cappello'))s+=`<path d="M-11 -4 C-5 -6 6 -6 12 -4 C6 -2 -5 -2 -11 -4 Z" fill="${HAT}" class="k" stroke-width="1"></path><path d="M-5 -5 C-5 -11 6 -11 6 -5 Z" fill="${HAT}" class="k" stroke-width="1"></path>`;
 return s+'</g>'}
